const testMidasProtocolTarget = async () => {
  const rpcURL = "https://bsc-dataseed.binance.org";
  const signer = new Wallet(process.env.PRIVATE_KEY ?? "", new providers.JsonRpcProvider(rpcURL));
  const signerAddress = signer.address;

  // ORIGIN SIDE
  const BNB_NATIVE = constants.AddressZero;
  const BNB_USDC = "0x8AC76a51cc950d9822D68b83fE1Ad97B32Cd580d";
  const amountIn = BigNumber.from("5000000000000000");
  const fromAsset = BNB_NATIVE;
  const toAsset = BNB_USDC;

  // DESTINATION SIDE
  const POLYGON_WETH = "0x7ceB23fD6bC0adD59E62ac25578270cFf1b9f619";
  const POLYGON_USDC = "0x2791bca1f2de4661ed88a30c99a7a9449aa84174";
  const POLYGON_CTOKEN_WETH = "0xD809c769A04246855fee98423B180C7CCa6bF07c"; // https://app.midascapital.xyz/137/pool/5
  const midasProtocolTarget = "0xDF97CadbcCeE9cfdB12A3e9BB7663E6753A71a0C";

  // Params for calldata generation
  const POLYGON_DOMAIN_ID = "1886350457";
  const POLYGON_RPC_URL = "https://polygon.llamarpc.com";
  const swapper = Swapper.UniV3;
  const poolFee = await getPoolFeeForUniV3(POLYGON_DOMAIN_ID, POLYGON_RPC_URL, POLYGON_WETH, POLYGON_USDC);

  const params: DestinationCallDataParams = {
    fallback: signerAddress,
    swapForwarderData: {
      toAsset: POLYGON_WETH,
      swapData: {
        amountOutMin: "0",
        poolFee: poolFee,
      },
    },
  };

  const forwardCallData = defaultAbiCoder.encode(
    ["address", "address", "address"],
    [POLYGON_CTOKEN_WETH, POLYGON_WETH, signerAddress],
  );
  const callDataForMidasProtocolTarget = await getXCallCallData(POLYGON_DOMAIN_ID, swapper, forwardCallData, params);
  const swapAndXCallParams = {
    originDomain: "6450786",
    destinationDomain: "1886350457",
    fromAsset, // BNB
    toAsset, // USDC
    amountIn: amountIn.toString(),
    to: midasProtocolTarget,
    relayerFeeInNativeAsset: "1000000000000000", // 0.001 BNB
    callData: callDataForMidasProtocolTarget,
  };

  // estimate output amount
  const amountOutAfterXcall = await getSwapAmountOut(
    {
      domainId: "6450786",
      fromAsset,
      toAsset,
      amountIn: amountIn.toString(),
      rpc: rpcURL,
    },
    true,
  );
  console.log(`amountOut after xcall (bnb -> usdc): ${amountOutAfterXcall.toString()}`);

  const amountOutAfterExecute = await getSwapAmountOut(
    {
      domainId: "1886350457",
      fromAsset: POLYGON_USDC,
      toAsset: POLYGON_WETH,
      amountIn: BigNumber.from(amountOutAfterXcall).div(BigNumber.from(10).pow(12)).mul(9995).div(10000).toString(),
      rpc: POLYGON_RPC_URL,
      fee: poolFee,
    },
    false,
  );
  console.log(`amountOut after execute (usdc -> weth): ${amountOutAfterExecute.toString()}`);

  const amountOutDestination = await getBridgeAmountOut(
    {
      domainId: "6450786",
      fromAsset,
      toAsset,
      amountIn: amountIn.toString(),
      rpc: rpcURL,
    },
    {
      domainId: "1886350457",
      fromAsset: POLYGON_USDC,
      toAsset: POLYGON_WETH,
      amountIn: amountIn.toString(),
      rpc: POLYGON_RPC_URL,
    },
    18,
    6,
  );
  console.log(`amountOut on destination: ${amountOutDestination.toString()}`);

  const txRequest = await prepareSwapAndXCall(swapAndXCallParams, signerAddress);
  if (txRequest) {
    const tx = await signer.sendTransaction({ ...txRequest });
    console.log(`SwapAndXCall tx mined. tx: ${tx.hash}`);
    await tx.wait();
  }
};

testMidasProtocolTarget();

import { expect, mkAddress } from "@connext/nxtp-utils";
import { stub, SinonStub, reset, restore } from "sinon";
import { defaultAbiCoder } from "ethers/lib/utils";
import { constants } from "ethers";
import {
  getDestinationSwapDataForOneInch,
  getDestinationSwapDataForUniV2,
  getOriginSwapDataForOneInch,
  getOriginSwapDataForUniV2,
  getOriginSwapDataForUniV3,
  getDestinationSwapDataForUniV3,
} from "../../src/helpers/swapdata";
import * as MockableFns from "../../src/mockable";

const mockOriginSwapDataArgs = {
  chainId: 1337,
  fromAsset: mkAddress("0x1"),
  toAsset: mkAddress("0x2"),
  amountIn: "100",
  fromAddress: mkAddress("0x11"),
  config: {
    apiKey: "12345",
  },
};

describe("Helpers:swapdata", () => {
  describe("#getOriginSwapDataForUniV2", () => {
    it("should throw", () => {
      expect(getOriginSwapDataForUniV2(mockOriginSwapDataArgs)).to.be.throw;
    });
  });
  describe("#getOriginSwapDataForUniV3", () => {
    it("should throw", () => {
      expect(getOriginSwapDataForUniV3(mockOriginSwapDataArgs)).to.be.throw;
    });
  });
  describe("#getOriginSwapDataForOneInch", () => {
    let axiosGetStub: SinonStub;
    beforeEach(() => {
      axiosGetStub = stub(MockableFns, "axiosGet");
    });
    afterEach(() => {
      restore();
      reset();
    });
    it("should throw if axioGet fails", () => {
      axiosGetStub.throws();
      expect(getOriginSwapDataForOneInch(mockOriginSwapDataArgs)).to.be.throw;
    });
    it("should work with the default slippage", async () => {
      axiosGetStub.resolves({ data: { tx: { data: "0xaaa" } } });
      const swapData = await getOriginSwapDataForOneInch(mockOriginSwapDataArgs);
      expect(axiosGetStub.getCall(0).args[0]).to.be.deep.eq(
        "https://api.1inch.dev/swap/v5.2/1337/swap?src=0x1000000000000000000000000000000000000000&dst=0x2000000000000000000000000000000000000000&amount=100&from=0x1100000000000000000000000000000000000000&slippage=1&disableEstimate=true",
      );
      expect(swapData).to.be.eq("0xaaa");
    });
    it("should work with the origin native asset", async () => {
      const swapDataArgs = { ...mockOriginSwapDataArgs, slippage: 100, fromAsset: constants.AddressZero };
      axiosGetStub.resolves({ data: { tx: { data: "0xaaa" } } });
      const swapData = await getOriginSwapDataForOneInch(swapDataArgs);
      expect(axiosGetStub.getCall(0).args[0]).to.be.eq(
        "https://api.1inch.dev/swap/v5.2/1337/swap?src=0xEeeeeEeeeEeEeeEeEeEeeEEEeeeeEeeeeeeeEEeE&dst=0x2000000000000000000000000000000000000000&amount=100&from=0x1100000000000000000000000000000000000000&slippage=100&disableEstimate=true",
      );
      expect(swapData).to.be.eq("0xaaa");
    });
    it("should work with the destination native asset", async () => {
      const swapDataArgs = { ...mockOriginSwapDataArgs, slippage: 100, toAsset: constants.AddressZero };
      axiosGetStub.resolves({ data: { tx: { data: "0xaaa" } } });
      const swapData = await getOriginSwapDataForOneInch(swapDataArgs);
      expect(axiosGetStub.getCall(0).args[0]).to.be.eq(
        "https://api.1inch.dev/swap/v5.2/1337/swap?src=0x1000000000000000000000000000000000000000&dst=0xEeeeeEeeeEeEeeEeEeEeeEEEeeeeEeeeeeeeEEeE&amount=100&from=0x1100000000000000000000000000000000000000&slippage=100&disableEstimate=true",
      );
      expect(swapData).to.be.eq("0xaaa");
    });
  });
  describe("#getDestinationSwapDataForUniV2", () => {
    it("should work", async () => {
      const amountOutMin = "100";
      const res = await getDestinationSwapDataForUniV2({ amountOutMin });
      expect(res).to.be.eq(defaultAbiCoder.encode(["uint256"], [amountOutMin]));
    });
  });
  describe("#getDestinationSwapDataForUniV3", () => {
    it("should work", async () => {
      const amountOutMin = "100";
      const poolFee = "500";
      const res = await getDestinationSwapDataForUniV3({ amountOutMin, poolFee });
      expect(res).to.be.eq(defaultAbiCoder.encode(["uint24", "uint256"], [poolFee, amountOutMin]));
    });
  });
  describe("#getDestinationSwapDataForOneInch", () => {
    it("should throw", async () => {
      const mockArgs = {};
      await expect(getDestinationSwapDataForOneInch(mockArgs)).to.be.rejectedWith("ToDo");
    });
  });
});

import { expect, mkAddress, mock } from "@connext/nxtp-utils";
import { stub, reset, restore } from "sinon";
import { getSwapPathForUniV3, getSwapPathForUniV2, getPathForPanCake } from "../../src/helpers/swaputil";
import * as MockableFns from "../../src/mockable";
import { Token, TradeType, CurrencyAmount } from "@uniswap/sdk-core";
import { Fetcher, Pair, Token as _Token, TokenAmount, Route, Trade, JSBI } from "@uniswap/sdk";
import { FeeAmount, encodeRouteToPath } from "@uniswap/v3-sdk";
import * as UniFuncs from "@uniswap/v3-sdk";
import {
  Fetcher as PancakeFetcher,
  Pair as PancakePair,
  Token as PancakeToken,
  Route as PancakeRoute,
  Trade as PancakeTrade,
  CurrencyAmount as PancakeCurrencyAmount,
} from "@pancakeswap/sdk";
import { AlphaRouter } from "@uniswap/smart-order-router";
import { ethers } from "ethers";

const mockSwapQuoteCallbackArgs = {
  chainId: 1337,
  quoter: mkAddress("0x123"),
  rpc: "http://localhost:8545",
  fromAsset: mkAddress("0x1"),
  toAsset: mkAddress("0x2"),
  amountIn: "10000000000000000000000",
  fee: "300",
};

class MockJsonRpcProvider {
  public getBlockNumber = stub().resolves(1232132);
}

describe("Helpers:swapUtil", () => {
  beforeEach(() => {
    stub(MockableFns, "JsonRpcProvider").value(MockJsonRpcProvider);
  });

  afterEach(() => {
    restore();
    reset();
  });
  const mockArgs = {
    fromTokenContractAddress: "0x8f3Cf7ad23Cd3CaDbD9735AFf958023239c6A063",
    toTokenContractAddress: "0x2791Bca1f2de4661ED88A30C99A7a9449Aa84174",
    chainId: 1,
    rpc: "http://localhost:8545",
    fromTokenDecimal: 18,
    toTokenDecimal: 18,
    amount: "1000000000000000000", // 1 token for example
    signerAddress: mkAddress("1"),
  };

  describe("#getSwapPathForUniV3", () => {
    it("should work", async () => {
      const FEE_SIZE = 3;

      function encodePath(path: string[], fees: FeeAmount[]): string {
        if (path.length != fees.length + 1) {
          throw new Error("path/fee lengths do not match");
        }

        let encoded = "0x";
        for (let i = 0; i < fees.length; i++) {
          // 20 byte encoding of the address
          encoded += path[i].slice(2);
          // 3 byte encoding of the fee
          encoded += fees[i].toString(16).padStart(2 * FEE_SIZE, "0");
        }
        // encode the final token
        encoded += path[path.length - 1].slice(2);

        return encoded.toLowerCase();
      }
      const token0 = new Token(1, mockArgs.fromTokenContractAddress, 18);
      const token1 = new Token(1, mockArgs.toTokenContractAddress, 18);
      const fakeRoute = {
        quote: CurrencyAmount.fromRawAmount(new Token(1, mockArgs.toTokenContractAddress, 18), "1000000000000000000"),
        route: [
          // {
          //   tokenPath: [
          //     new Token(1, mockArgs.fromTokenContractAddress, 18),
          //     new Token(1, mockArgs.toTokenContractAddress, 18),
          //   ],
          //   route: {
          //     protocol: "V3",
          //   },
          // },
          {
            _midPrice: null,
            pools: [
              {
                token0: [token0],
                token1: [token1],
                fee: 100,
                sqrtRatioX96: [JSBI],
                liquidity: [JSBI],
                tickCurrent: 276325,
                tickDataProvider: {},
              },
            ],
            tokenPath: [token0, token1],
            input: token0,
            output: token1,
            route: {
              protocol: "V3",
            },
          },
        ],
      };

      stub(ethers.providers, "JsonRpcProvider").returns({});
      stub(UniFuncs, "encodeRouteToPath").returns("1234");
      stub(AlphaRouter.prototype, "route").resolves(fakeRoute as any);
      const result = await getSwapPathForUniV3(mockArgs);
      console.log(result, "resultfrom");
      const path = "1234";
      console.log(result.route, "pepepe");
      expect(result).to.deep.equal({
        quote: fakeRoute.quote,
        tokenPath: path,
        route: "V3",
      });
    });

    it("should throw an error if no routes found", async () => {
      stub(AlphaRouter.prototype, "route").resolves(null);
      await expect(getSwapPathForUniV3(mockArgs)).to.be.throw;
    });

    it("should propagate any error occurred while getting paths", async () => {
      const fakeError = new Error("Something went wrong");
      stub(AlphaRouter.prototype, "route").rejects(fakeError);

      await expect(getSwapPathForUniV3(mockArgs)).to.be.throw;
    });
  });

  describe("#getSwapPathForUniV2", () => {
    it("should work", async () => {
      const tokenIn = new _Token(mockArgs.chainId, mockArgs.fromTokenContractAddress, 18);
      const tokenOut = new _Token(mockArgs.chainId, mockArgs.toTokenContractAddress, 18);
      const amountIn = new TokenAmount(
        tokenIn,
        ethers.utils.parseUnits(mockArgs.amount, mockArgs.fromTokenDecimal).toString(),
      );
      const amountOut = new TokenAmount(
        tokenOut,
        ethers.utils.parseUnits(mockArgs.amount, mockArgs.toTokenDecimal).toString(),
      );

      const pair = new Pair(amountIn, amountOut);
      const route = new Route([pair], tokenIn);
      const trade = new Trade(route, amountIn, TradeType.EXACT_INPUT);

      stub(ethers.providers, "JsonRpcProvider").returns({});
      stub(Fetcher, "fetchPairData").resolves(pair);
      const result = await getSwapPathForUniV2(mockArgs);
      expect(result).to.be.deep.equal({
        quote: trade.outputAmount.toSignificant(),
        tokenPath: route.path.map((token) => token.address),
        route: "V2",
      });
    });

    it("should propagate any error occurred while getting paths", async () => {
      const fakeError = new Error("Something went wrong");
      stub(Fetcher, "fetchPairData").rejects(fakeError);

      await expect(getSwapPathForUniV2(mockArgs)).to.be.throw;
    });
  });

  describe("#getPathForPanCake", () => {
    it("should work", async () => {
      const tokenIn = new PancakeToken(mockArgs.chainId, mockArgs.fromTokenContractAddress, 18, "");
      const tokenOut = new PancakeToken(mockArgs.chainId, mockArgs.toTokenContractAddress, 18, "");

      const amountIn = PancakeCurrencyAmount.fromRawAmount(tokenIn, mockArgs.amount);
      const amountOut = PancakeCurrencyAmount.fromRawAmount(tokenOut, mockArgs.amount);
      const pair = new PancakePair(amountIn, amountOut);
      const route = new PancakeRoute([pair], tokenIn, tokenOut);
      const trade = new PancakeTrade(route, amountIn, TradeType.EXACT_INPUT);

      stub(ethers.providers, "JsonRpcProvider").returns({});
      stub(PancakeFetcher, "fetchPairData").resolves(pair);
      const result = await getPathForPanCake(mockArgs);
      expect(result).to.be.deep.equal({
        quote: trade.outputAmount.toSignificant(),
        tokenPath: route.path.map((token) => token.address),
        route: "PANCAKE",
      });
    });

    it("should propagate any error occurred while getting paths", async () => {
      const fakeError = new Error("Something went wrong");
      stub(PancakeFetcher, "fetchPairData").rejects(fakeError);

      await expect(getPathForPanCake(mockArgs)).to.be.throw;
    });
  });
});

import { expect, mkAddress } from "@connext/nxtp-utils";
import { stub, SinonStub, reset, restore } from "sinon";
import { constants } from "ethers";
import { getSwapQuoteForOneInch, getSwapQuoteForUniV2, getSwapQuoteForUniV3 } from "../../src/helpers/swapquote";
import * as MockableFns from "../../src/mockable";

const mockSwapQuoteCallbackArgs = {
  chainId: 1337,
  quoter: mkAddress("0x123"),
  rpc: "http://localhost:8545",
  fromAsset: mkAddress("0x1"),
  toAsset: mkAddress("0x2"),
  amountIn: "10000000000000000000000",
  fee: "300",
  config: {
    apiKey: "12345",
  },
};

class MockJsonRpcProvider {
  public getBlockNumber = stub().resolves(1232132);
}

describe("Helpers:swapquote", () => {
  beforeEach(() => {
    stub(MockableFns, "JsonRpcProvider").value(MockJsonRpcProvider);
  });

  afterEach(() => {
    restore();
    reset();
  });

  describe("#getSwapQuoteForUniV2", () => {
    it("should throw with invalid rpc", async () => {
      expect(getSwapQuoteForUniV2(mockSwapQuoteCallbackArgs)).to.be.throw;
    });
    it("should work", async () => {
      stub(MockableFns, "getContract").returns({
        getAmountsOut: stub().resolves(["100", "999"]),
      } as any);
      expect(await getSwapQuoteForUniV2(mockSwapQuoteCallbackArgs)).to.be.eq("999");
    });
  });

  describe("#getSwapQuoteForUniV3", () => {
    it("should throw with invalid rpc", async () => {
      expect(getSwapQuoteForUniV3(mockSwapQuoteCallbackArgs)).to.be.throw;
    });
    it("should work", async () => {
      stub(MockableFns, "getContract").returns({
        callStatic: { quoteExactInputSingle: stub().resolves(["999"]) },
      } as any);
      expect(await getSwapQuoteForUniV3(mockSwapQuoteCallbackArgs)).to.be.eq("999");
    });
  });

  describe("#getSwapQuoteForOneInch", () => {
    let axiosGetStub: SinonStub;

    beforeEach(() => {
      axiosGetStub = stub(MockableFns, "axiosGet");
    });

    afterEach(() => {
      restore();
      reset();
    });

    it("should throw if axioGet fails", () => {
      axiosGetStub.throws();
      expect(getSwapQuoteForOneInch(mockSwapQuoteCallbackArgs)).to.be.throw;
    });

    it("should work with the origin native asset", async () => {
      const args = { ...mockSwapQuoteCallbackArgs, fromAsset: constants.AddressZero };
      axiosGetStub.resolves({ data: { toAmount: "999" } });

      const amountOut = await getSwapQuoteForOneInch(args);
      expect(axiosGetStub.getCall(0).args[0]).to.be.eq(
        "https://api.1inch.dev/swap/v5.2/1337/quote?src=0xEeeeeEeeeEeEeeEeEeEeeEEEeeeeEeeeeeeeEEeE&dst=0x2000000000000000000000000000000000000000&amount=10000000000000000000000&from=0x1230000000000000000000000000000000000000&slippage=1",
      );
      expect(amountOut).to.be.eq("999");
    });

    it("should work with the destination native asset", async () => {
      const args = { ...mockSwapQuoteCallbackArgs, toAsset: constants.AddressZero };
      axiosGetStub.resolves({ data: { toAmount: "999" } });
      const amountOut = await getSwapQuoteForOneInch(args);
      expect(axiosGetStub.getCall(0).args[0]).to.be.eq(
