import { expect, mkAddress } from "@connext/nxtp-utils";
import { SinonStub, restore, reset, stub } from "sinon";
import { ethers } from "ethers";

import { getPriceImpactForSwaps, getSlippageDistribution, getAmountOutMinForUniV3 } from "../../../src/libs/shared";
import * as quoteModule from "../../../src/libs/shared/quote";
import * as slippageModule from "../../../src/libs/shared/slippage";
import * as assetModule from "../../../src/helpers/asset";

describe("Libs:slippage", () => {
  const originChain = 1337;
  const originDomain = 133712;
  const destinationChain = 1338;
  const destinationDomain = 133812;
  const inputToken = mkAddress("0x1");
  const outputToken = mkAddress("0x2");
  const inputDecimal = 18;
  const outputDecimal = 18;
  const signerAddress = mkAddress("0x3");
  const originRpc = "https://origin-provider.io";
  const destinationRpc = "https://destination-provider.io";

  let getEstimateAmountReceivedStub: SinonStub;
  let getCoingeckoIDsStub: SinonStub;
  let getTokenPricesInUsdStub: SinonStub;

  beforeEach(() => {
    getCoingeckoIDsStub = stub(assetModule, "getCoingeckoIDs");
    getTokenPricesInUsdStub = stub(assetModule, "getTokenPricesInUsd");
    getEstimateAmountReceivedStub = stub(quoteModule, "getEstimateAmountReceived");
  });

  afterEach(() => {
    restore();
    reset();
  });

  describe("#getPriceImpactForSwaps", () => {
    const amountIn = ethers.utils.parseUnits("10", inputDecimal);

    it("should calculate price impact correctly", async () => {
      getEstimateAmountReceivedStub.resolves(ethers.utils.parseUnits("5", 18).toString());
      getCoingeckoIDsStub.resolves({ [inputToken]: "inputTokenId", [outputToken]: "outputTokenId" });
      getTokenPricesInUsdStub.resolves([10000, 5000]);

      const priceImpact = await getPriceImpactForSwaps(
        inputToken,
        inputDecimal,
        originChain,
        originRpc,
        outputToken,
        outputDecimal,
        amountIn,
        signerAddress,
      );

      expect(priceImpact).to.equal(50);
    });

    it("should throw an error if the estimate calls fails", async () => {
      getEstimateAmountReceivedStub.throws();

      await expect(
        getPriceImpactForSwaps(
          inputToken,
          inputDecimal,
          originChain,
          originRpc,
          outputToken,
          outputDecimal,
          amountIn,
          signerAddress,
        ),
      ).to.be.rejectedWith(Error, `Failed to get Price Impact`);
    });
  });

  describe("#getSlippageDistribution", () => {
    let getPriceImpactForSwapsStub: SinonStub;

    const amountIn = ethers.utils.parseUnits("10", 18);
    const slippage = "300";

    beforeEach(() => {
      getPriceImpactForSwapsStub = stub(slippageModule, "getPriceImpactForSwaps");
    });

    afterEach(() => {
      restore();
      reset();
    });

    it("should calculate slippage distribution correctly", async () => {
      getEstimateAmountReceivedStub.resolves(ethers.utils.parseUnits("5", 18).toString());
      getPriceImpactForSwapsStub.resolves(10);

      const slippageDistribution = await getSlippageDistribution(
        inputToken,
        originDomain,
        destinationDomain,
        originRpc,
        destinationRpc,
        outputToken,
        outputDecimal,
        amountIn,
        signerAddress,
        inputDecimal,
        slippage,
      );

      expect(slippageDistribution).to.deep.equal({
        originSlippage: 12,
        destinationSlippage: 12,
        connextSlippage: 276,
      });
    });

    it("should throw an error if inputToken is the same as outputToken", async () => {
      const slippage = "300";

      await expect(
        getSlippageDistribution(
          inputToken,
          originDomain,
          destinationDomain,
          originRpc,
          destinationRpc,
          inputToken,
          inputDecimal,
          amountIn,
          signerAddress,
          inputDecimal,
          slippage,
        ),
      ).to.be.rejectedWith(Error, "Slippage cannot be calculated in same tokens");
    });
  });

  describe("#getAmountOutMinForUniV3", () => {
    const amountIn = ethers.utils.parseUnits("10", 18);
    const quoteAmountOut = ethers.utils.parseUnits("5", 18);
    const slippage = "300";

    it("should calculate the minimum amount out correctly", async () => {
      const expectedAmountOutMin =
        parseFloat(ethers.utils.formatUnits(quoteAmountOut, outputDecimal)) * (1 - +slippage);

      getEstimateAmountReceivedStub.resolves(quoteAmountOut);

      const amountOutMin = await getAmountOutMinForUniV3(
        inputToken,
        outputToken,
        originRpc,
        originDomain,
        amountIn,
        signerAddress,
        +slippage,
        outputDecimal,
      );

      expect(amountOutMin).to.equal(expectedAmountOutMin);
    });

    it("should throw an error if the estimate call fails", async () => {
      getEstimateAmountReceivedStub.throws();

      await expect(
        getAmountOutMinForUniV3(
          inputToken,
          outputToken,
          originRpc,
          originDomain,
          amountIn,
          signerAddress,
          +slippage,
          outputDecimal,
        ),
      ).to.be.rejectedWith(Error, "Failed to get Minimum Amount Out for UniV3");
    });
  });
});

import { expect, mkBytes32, OriginTransfer, DestinationTransfer } from "@connext/nxtp-utils";

import { mock } from "../../mock";
import { mockPubContext } from "../../globalTestHook";
import { retryXCalls } from "../../../src/tasks/publisher/operations/retryXCalls";
import { SinonStub } from "sinon";
const mockInfo = {
  [mock.domain.A]: {
    latestBlockNumber: 1234567,
    latestNonce: 232323,
    safeConfirmations: 19,
  },
  [mock.domain.B]: {
    latestBlockNumber: 1234567,
    latestNonce: 454545,
    safeConfirmations: 28,
  },
};
const mockBlockNumber: Map<string, number> = new Map();

describe("Operations:retryXCalls", () => {
  let mockOriginSubgraphResponse: OriginTransfer[];
  let mockDestSubgraphResponse: DestinationTransfer[];
  let domainCount = 0;

  describe("#retryXCalls", () => {
    beforeEach(() => {
      mockBlockNumber.set(mock.domain.A, 1234567);
      mockBlockNumber.set(mock.domain.B, 1234567);

      (mockPubContext.adapters.cache.transfers.getLatestNonce as SinonStub).callsFake(
        (domain: string) => mockInfo[domain].latestNonce,
      );
      mockPubContext.config.chains[mock.domain.A].confirmations = mockInfo[mock.domain.A].safeConfirmations;
      mockPubContext.config.chains[mock.domain.B].confirmations = mockInfo[mock.domain.B].safeConfirmations;
      mockOriginSubgraphResponse = [
        mock.entity.xtransfer({ transferId: mkBytes32("0x1"), nonce: 9 }) as OriginTransfer,
        mock.entity.xtransfer({ transferId: mkBytes32("0x2"), nonce: 10 }) as OriginTransfer,
      ];
      mockDestSubgraphResponse = [
        mock.entity.xtransfer({ transferId: mkBytes32("0x1"), nonce: 9 }) as DestinationTransfer,
        mock.entity.xtransfer({ transferId: mkBytes32("0x2"), nonce: 10 }) as DestinationTransfer,
      ];
      (mockPubContext.adapters.subgraph.getLatestBlockNumber as SinonStub).resolves(mockBlockNumber);
      (mockPubContext.adapters.subgraph.getDestinationTransfers as SinonStub).resolves(mockDestSubgraphResponse);
      (mockPubContext.adapters.subgraph.getOriginTransfersByDomain as SinonStub).resolves(mockDestSubgraphResponse);
      (mockPubContext.adapters.cache.transfers.getPending as SinonStub).callsFake((domain: string) => [
        mockOriginSubgraphResponse[0].transferId,
        mockOriginSubgraphResponse[1].transferId,
      ]);
      (mockPubContext.adapters.cache.transfers.getTransfer as SinonStub).callsFake((transferId: string) =>
        mockOriginSubgraphResponse.filter((transfer) => transfer.transferId === transferId),
      );
      domainCount = Object.keys(mock.domain).length;
    });

    it("happy: should retry xcalls from the cache and publish them", async () => {
      (mockPubContext.adapters.subgraph.getDestinationTransfers as SinonStub).resolves([]);
      await retryXCalls();

      // Should have been called once per available/configured chain.
      expect((mockPubContext.adapters.cache.transfers.getTransfer as SinonStub).callCount).to.be.eq(
        mockOriginSubgraphResponse.length * domainCount,
      );
      expect((mockPubContext.adapters.mqClient.publish as SinonStub).callCount).to.be.eq(
        mockOriginSubgraphResponse.length * domainCount,
      );
      expect((mockPubContext.adapters.mqClient.publish as SinonStub).calledWithExactly(mockOriginSubgraphResponse[0]));
      expect((mockPubContext.adapters.mqClient.publish as SinonStub).calledWithExactly(mockOriginSubgraphResponse[1]));
      expect((mockPubContext.adapters.cache.transfers.setLatestNonce as SinonStub).calledWithExactly(mock.domain.A, 9));
      expect(
        (mockPubContext.adapters.cache.transfers.setLatestNonce as SinonStub).calledWithExactly(mock.domain.A, 10),
      );
    });

    it("should not publish if nothing is pending", async () => {
      await retryXCalls();

      expect((mockPubContext.adapters.mqClient.publish as SinonStub).callCount).to.be.eq(0);
      expect((mockPubContext.adapters.cache.transfers.getTransfer as SinonStub).callCount).to.be.eq(
        mockOriginSubgraphResponse.length * domainCount,
      );
    });

    it("should work with block number error", async () => {
      mockBlockNumber.set(mock.domain.A, 0);
      mockBlockNumber.set(mock.domain.B, 0);

      await expect(retryXCalls()).to.be.fulfilled;

      expect((mockPubContext.adapters.mqClient.publish as SinonStub).callCount).to.be.eq(0);
      expect((mockPubContext.adapters.cache.transfers.setLatestNonce as SinonStub).callCount).to.be.eq(0);
      expect((mockPubContext.adapters.cache.transfers.getTransfer as SinonStub).callCount).to.be.eq(
        mockOriginSubgraphResponse.length * domainCount,
      );
    });

    it("should work if pending set is empty", async () => {
      (mockPubContext.adapters.cache.transfers.getPending as SinonStub).resolves([]);
      (mockPubContext.adapters.subgraph.getOriginTransfersByDomain as SinonStub).resolves([]);
      await expect(retryXCalls()).to.be.fulfilled;

      expect((mockPubContext.adapters.mqClient.publish as SinonStub).callCount).to.be.eq(0);
      expect((mockPubContext.adapters.cache.transfers.setLatestNonce as SinonStub).callCount).to.be.eq(0);
      expect((mockPubContext.adapters.cache.transfers.getTransfer as SinonStub).callCount).to.be.eq(0);
    });

    it("should work if transfers cache is empty", async () => {
      (mockPubContext.adapters.cache.transfers.getTransfer as SinonStub).resolves(undefined);
      await expect(retryXCalls()).to.be.fulfilled;

      expect((mockPubContext.adapters.mqClient.publish as SinonStub).callCount).to.be.eq(0);
      expect((mockPubContext.adapters.cache.transfers.setLatestNonce as SinonStub).callCount).to.be.eq(0);
      expect((mockPubContext.adapters.cache.transfers.getTransfer as SinonStub).callCount).to.be.eq(
        mockOriginSubgraphResponse.length * domainCount,
      );
    });
  });
});

import { expect } from "@connext/nxtp-utils";
import { SinonStub } from "sinon";

import {
  HubDBHelper,
  SpokeDBHelper,
  OptimisticHubDBHelper,
} from "../../../../../src/tasks/prover/adapters/database/helper";
import { proverCtxMock } from "../../../../globalTestHook";

describe("#Database helper", () => {
  let hubHelper: HubDBHelper;
  let spokeHelper: SpokeDBHelper;
  let optimisticHubDBHelper: OptimisticHubDBHelper;

  beforeEach(() => {
    hubHelper = new HubDBHelper(
      "hub",
      10,
      {
        reader: proverCtxMock.adapters.database,
        writer: proverCtxMock.adapters.databaseWriter,
      },
      proverCtxMock.adapters.cache.messages,
    );
    spokeHelper = new SpokeDBHelper(
      "spoke",
      10,
      {
        reader: proverCtxMock.adapters.database,
        writer: proverCtxMock.adapters.databaseWriter,
      },
      proverCtxMock.adapters.cache.messages,
    );
    optimisticHubDBHelper = new OptimisticHubDBHelper(["node1", "node2"], 2);
  });

  it("spoke helper should get node", async () => {
    const node = "0xnode1";
    (proverCtxMock.adapters.database.getSpokeNode as SinonStub).returns(node);
    const first = await spokeHelper.getNode(0);
    const second = await spokeHelper.getNode(0);
    expect(first).eq(second);
    expect(node).eq(second);
  });
  it("spoke helper should get nodes", async () => {
    const nodes = ["0xnode1", "0xnode2"];
    (proverCtxMock.adapters.database.getSpokeNodes as SinonStub).returns(nodes);
    const first = await spokeHelper.getNodes(0, 2);
    const second = await spokeHelper.getNodes(0, 2);
    expect(first).eq(second);
    expect(nodes[0]).eq(second[0]);
    expect(nodes[1]).eq(second[1]);
  });

  it("hub helper should get node", async () => {
    const node = "0xnode1";
    (proverCtxMock.adapters.database.getHubNode as SinonStub).returns(node);
    const first = await hubHelper.getNode(0);
    const second = await hubHelper.getNode(0);
    expect(first).eq(second);
    expect(node).eq(second);
  });
  it("hub helper should get nodes", async () => {
    const nodes = ["0xnode1", "0xnode2"];
    (proverCtxMock.adapters.database.getHubNodes as SinonStub).returns(nodes);
    const first = await hubHelper.getNodes(0, 2);
    const second = await hubHelper.getNodes(0, 2);
    expect(first).eq(second);
    expect(nodes[0]).eq(second[0]);
    expect(nodes[1]).eq(second[1]);
  });

  it("spoke helper should get root", async () => {
    const root = "0xnode1";
    const first = await spokeHelper.getRoot("root");
    expect(first).eq(undefined);
    await spokeHelper.putRoot("root", root);
    const second = await spokeHelper.getRoot("root");
    expect(root).eq(second);
  });

  it("hub helper should get root", async () => {
    const root = "0xnode1";
    const first = await hubHelper.getRoot("root");
    expect(first).eq(undefined);
    await hubHelper.putRoot("root", root);
    const second = await hubHelper.getRoot("root");
    expect(root).eq(second);
  });

  it("hub helper should operate", async () => {
    await hubHelper.getNode(0);
    await hubHelper.getNodes(0, 2);
    await hubHelper.getRoot("0001");
    await hubHelper.putRoot("0001", "0xROOT");
    await hubHelper.getRoot("0001");
    await hubHelper.clearLocalCache();
    await hubHelper.clearCache();
    expect(await hubHelper.getCount()).eq(10);
  });

  it("spoke helper should operate", async () => {
    await spokeHelper.getNode(0);
    await spokeHelper.getNodes(0, 2);
    await spokeHelper.getRoot("0001");
    await spokeHelper.putRoot("0001", "0xROOT");
    await hubHelper.getRoot("0001");
    await spokeHelper.clearLocalCache();
    await spokeHelper.clearCache();
    expect(await spokeHelper.getCount()).eq(10);
  });

  it("optimisticHubDBHelper should get node", async () => {
    const node = await optimisticHubDBHelper.getNode(0);
    expect(node).eq("node1");
  });
  it("optimisticHubDBHelper should get count", async () => {
    const node = await optimisticHubDBHelper.getCount();
    expect(node).eq(2);
  });
  it("optimisticHubDBHelper should get nodes", async () => {
    const nodes = await optimisticHubDBHelper.getNodes(0, 1);
    expect(nodes.length).eq(2);
    expect(nodes[0]).eq("node1");
    expect(nodes[1]).eq("node2");
  });
  it("optimisticHubDBHelper putRoot noop", async () => {
    await optimisticHubDBHelper.putRoot();
    expect(optimisticHubDBHelper.putRoot).to.be.returned;
  });
  it("optimisticHubDBHelper should getRoot", async () => {
    const node = await optimisticHubDBHelper.getRoot();
    expect(node).eq(undefined);
  });
  it("optimisticHubDBHelper clearcache noop", async () => {
    await optimisticHubDBHelper.clearCache();
    expect(optimisticHubDBHelper.clearCache).to.be.returned;
  });
});
